import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {readdirSync,readFileSync,lstatSync,realpathSync,mkdirSync,writeFileSync,existsSync} from 'node:fs';import {resolve,join,relative,dirname,isAbsolute} from 'node:path';import {fileURLToPath} from 'node:url';import {REGISTRY,CATALOG_SHA,RUNTIME_SHA} from '../src/product-locale-chrome-pins.mjs';
const BASE='137cc1cdc1dc783fa4cedadf3e16619a07c9cfa6f6559cb8d2f449b7603120db',INDEX='51e08577d212f9d8f90095ada1d2acd2e6a373d3f9d8e875e8833e107c06dea4';const sha=b=>createHash('sha256').update(b).digest('hex');
function walk(root,dir=root){return readdirSync(dir).flatMap(n=>{const p=join(dir,n),s=lstatSync(p);assert.ok(!s.isSymbolicLink());if(s.isDirectory())return walk(root,p);assert.ok(s.isFile());return [relative(root,p).split('\\').join('/')];});}
export function patchIndex(bytes){assert.equal(sha(bytes),INDEX);let s=bytes.toString('utf8');for(const [a,b] of [['  <script type="module" src="./media/boot.mjs"></script>','  <script type="module" src="./media/boot.mjs"></script>\n  <link rel="stylesheet" href="./src/product-locale-chrome.css">\n  <script type="module" src="./src/product-locale-chrome-boot.mjs"></script>'],['    <section class="workspace" aria-label="実績とコレクション">','    <section class="workspace" aria-label="実績とコレクション">\n      <div id="hkiaLocaleChrome"></div>']]){assert.equal(s.split(a).length,2);s=s.replace(a,b);}return Buffer.from(s);}
const [base,manifest,bundle,locale,out]=process.argv.slice(2).map(x=>resolve(x));assert.ok(base&&manifest&&bundle&&locale&&out&&!existsSync(out),'fresh output');const mBytes=readFileSync(manifest);assert.equal(sha(mBytes),BASE);const m=JSON.parse(mBytes);assert.equal(m.writer,'OFF');assert.equal(m.entries,4146);assert.equal(m.webp,4076);const paths=walk(base).sort();assert.deepEqual(paths,Object.keys(m.files).sort());let bytes=0;for(const p of paths){const b=readFileSync(join(base,p));assert.equal(b.length,m.files[p].bytes,p);assert.equal(sha(b),m.files[p].sha256,p);bytes+=b.length;}assert.equal(bytes,m.bytes);
const target=join(realpathSync(dirname(out)),out.split(/[\\/]/).at(-1));for(const dir of [base,bundle,locale]){const r=relative(realpathSync(dir),target);assert.ok(r==='..'||r.startsWith('../')||r.startsWith('..\\')||isAbsolute(r),'output outside inputs');}
assert.deepEqual(walk(bundle).sort(),['product-locale-chrome.css','product-locale-chrome.mjs']);const files=new Map([['index.html',patchIndex(readFileSync(join(base,'index.html')))]]);const add=(path,body,expected)=>{assert.ok(!Object.hasOwn(m.files,path)&&!files.has(path));if(expected)assert.equal(sha(body),expected);files.set(path,body);};for(const n of ['product-locale-chrome.css','product-locale-chrome.mjs']){const b=readFileSync(join(bundle,n));assert.ok(b.length>0&&b.length<1024*1024&&!b.toString('utf8').includes('sourceMappingURL='));add('src/'+n,b);}
add('src/product-locale-chrome-boot.mjs',readFileSync(fileURLToPath(new URL('../product-locale-chrome-boot.mjs',import.meta.url))));add('localization/runtime.mjs',readFileSync(join(locale,'runtime.mjs')),RUNTIME_SHA);for(const r of REGISTRY)add('localization/ui/'+r.id+'.json',readFileSync(join(locale,'ui',r.id+'.json')),CATALOG_SHA[r.id]);assert.equal(files.size,20);
const changes={};for(const [p,b] of files){mkdirSync(dirname(join(out,p)),{recursive:true});writeFileSync(join(out,p),b);changes[p]={kind:p==='index.html'?'MOD':'ADD',...(p==='index.html'?{before:INDEX}:{}),after:sha(b),bytes:b.length};}const result={schema:'HKIA.ProductLocaleChromeDelta.1',baseManifestSha256:BASE,writer:'OFF_UNCHANGED',baseEntries:4146,unchanged:4145,scope:'32 static editor labels; no game packs; no shared app change',changes};writeFileSync(join(out,'delta-manifest.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
